(function () {
  'use strict';
  // Roth IRA projection, annual steps: each contribution is deposited at the start of the year and
  // the balance grows at the expected return, balance = (balance + c) x (1 + r). Qualified
  // withdrawals are tax-free, so the balance is also the after-tax value.
  // Contribution limit: the 2026 limit for that year's age, reduced by the IRC 408A(c)(3) MAGI
  // phase-out: limit x (top of range - MAGI) / range width, rounded up to the next $10 with a
  // $200 minimum (IRS Pub. 590-A worksheet 2-2). Taxable comparison (new contributions only):
  // the same after-tax dollars, with earnings taxed every year at the entered rate.
  // CHECKS (Node, scratch tests): $6,000/yr at 6% for 35 years = 6,000 x 1.06 x (1.06^35 - 1) /
  // 0.06 = $708,725.20, plus $10,000 x 1.06^35 = $76,860.87 -> $785,586; single MAGI $160,000 ->
  // 7,500 x 8,000 / 15,000 = $4,000; MAGI $167,990 -> $10 raised to $200; $168,000 -> $0;
  // MFJ $245,000 -> $5,250; age 50 single $160,000 -> 8,600 x 8 / 15 = $4,586.67 -> $4,590;
  // MFS $5,000 -> $3,750; taxable side = 6,000 x 1.0468 x (1.0468^35 - 1) / 0.0468.
  // ---- 2026 ROTH IRA LIMITS (tax year 2026) ------------------------------------------------
  // Source: IRS Notice 2025-67 (2026 cost-of-living adjustments): IRC 219(b)(5) limit $7,500,
  // age-50 catch-up $1,100; IRC 408A(c)(3) MAGI phase-out ranges. MFS range is fixed by statute.
  var IRA = {
    year: 2026,
    limit: 7500,
    catchUp50: 1100,
    rothRange: { single: [153000, 168000], mfj: [242000, 252000], mfs: [0, 10000] }
  };
  // --------------------------------------------------------------------------------------------

  function ageLimit(age) { return IRA.limit + (age >= 50 ? IRA.catchUp50 : 0); }

  function phaseOut(limit, magi, range) {
    if (magi <= range[0]) return limit;
    if (magi >= range[1]) return 0;
    var reduced = Math.ceil(limit * (range[1] - magi) / (range[1] - range[0]) / 10 - 1e-9) * 10;
    return Math.min(limit, Math.max(200, reduced));
  }

  function rothLimit(age, status, magi) { return phaseOut(ageLimit(age), magi, IRA.rothRange[status]); }

  // p: age, retireAge, balance, contrib, max (bool), rate, tax (decimals), status, magi.
  function project(p) {
    var n = p.retireAge - p.age, bal = p.balance, rows = [], total = 0, capped = false;
    var rothNew = 0, taxable = 0, taxableRate = p.rate * (1 - p.tax);
    for (var y = 0; y < n; y++) {
      var age = p.age + y, lim = rothLimit(age, p.status, p.magi);
      var c = p.max ? lim : Math.min(p.contrib, lim);
      if (!p.max && p.contrib > lim + 0.005) capped = true;
      var start = bal + c;
      bal = start * (1 + p.rate);
      rothNew = (rothNew + c) * (1 + p.rate);
      taxable = (taxable + c) * (1 + taxableRate);
      total += c;
      rows.push({ age: age, c: c, growth: bal - start, balance: bal, taxable: taxable });
    }
    return { balance: bal, total: total, growth: bal - p.balance - total, capped: capped, rows: rows,
             rothNew: rothNew, taxable: taxable };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('roAge')), retireAge = Math.round(num('roRetireAge')), balance = num('roBalance'),
        contrib = num('roContrib'), rate = num('roRate'), tax = num('roTax'), magi = num('roMagi'),
        status = document.getElementById('roStatus').value, max = document.getElementById('roMax').checked;
    var error = document.getElementById('roError');
    var bad = [age, retireAge, balance, contrib, rate, tax, magi].some(isNaN) || age < 16 || age > 99 ||
              retireAge <= age || retireAge > 100 || balance < 0 || contrib < 0 || rate < 0 || rate > 30 ||
              tax < 0 || tax > 60 || magi < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99, a retirement age above it (up to 100), non-negative amounts, ' +
                          'a return up to 30% and a tax rate up to 60%.';
      return;
    }
    var r = project({ age: age, retireAge: retireAge, balance: balance, contrib: contrib, max: max,
                      rate: rate / 100, tax: tax / 100, status: status, magi: magi });
    var range = IRA.rothRange[status], lim0 = rothLimit(age, status, magi), full0 = ageLimit(age);
    set('roFutureLabel', 'Roth IRA at age ' + retireAge);
    set('roFuture', money.format(r.balance));
    set('roContribTotal', money.format(r.total));
    set('roGrowth', money.format(r.growth));
    set('roLimit', money.format(lim0));
    var note;
    if (lim0 >= full0) note = 'Your income is below the ' + IRA.year + ' phase-out range (' + money.format(range[0]) + ' to ' +
        money.format(range[1]) + '), so you can contribute the full ' + money.format(full0) + '.';
    else if (lim0 > 0) note = 'Your income is inside the ' + IRA.year + ' phase-out range (' + money.format(range[0]) + ' to ' +
        money.format(range[1]) + '), so your limit is reduced from ' + money.format(full0) + '.';
    else note = 'Your income is at or above ' + money.format(range[1]) + ', so you can\'t contribute directly to a Roth IRA for ' + IRA.year + '.';
    set('roLimitNote', lim0 > 0 ? note + ' The limit is shared with any traditional IRA contributions.' : note);
    var capEl = document.getElementById('roCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('roCapped', 'Your planned contribution is above your limit in some years, so the projection uses the limit instead.');
    set('roCmpRoth', money.format(r.rothNew));
    set('roCmpTaxable', money.format(r.taxable));
    set('roCmpDiff', money.format(r.rothNew - r.taxable));
    var body = document.getElementById('roSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.c), money.format(row.growth), money.format(row.balance), money.format(row.taxable)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('roForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
